BEGIN; DO $$ BEGIN IF to_regclass('public.phoi_transactions') IS NULL OR to_regclass('public.inventory_transactions') IS NULL OR to_regprocedure('public.require_approved_active_user()') IS NULL OR to_regprocedure('public.inventory_update_manual_transaction(uuid,date,uuid,numeric,numeric,text,uuid)') IS NULL OR to_regprocedure('public.inventory_adjust_manual_transaction(uuid,numeric,date,numeric,text)') IS NULL OR to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])') IS NULL OR to_regprocedure('public.inventory_lock_product(uuid)') IS NULL OR to_regprocedure('public.inventory_assert_no_negative_product_after(uuid,date)') IS NULL OR to_regprocedure('public.inventory_guard_transactions()') IS NULL OR to_regprocedure('public.inventory_actor_can_change_transaction(date)') IS NULL OR to_regprocedure('public.inventory_calculate_product_stock_v1(text,text,text)') IS NULL THEN RAISE EXCEPTION 'Thieu backend kho an toan. Dung cai dat va kiem tra preflight.'; END IF; IF pg_get_functiondef(to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])')) NOT ILIKE '%inventory_assert_no_negative_product_after%' OR pg_get_functiondef(to_regprocedure('public.inventory_guard_transactions()')) NOT ILIKE '%inventory_assert_no_negative_product_after%' THEN RAISE EXCEPTION 'Hang rao kho chua dung tong ma hang. Dung cai dat va kiem tra preflight.'; END IF; IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.inventory_transactions'::regclass AND tgfoid=to_regprocedure('public.inventory_guard_transactions()') AND tgenabled='O') THEN RAISE EXCEPTION 'Hang rao ton kho chua duoc bat tren bang giao dich.'; END IF; END $$; CREATE OR REPLACE FUNCTION public.inventory_normalize_receipt_supplier_code_v1(p_code text) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path=public,pg_temp AS $$ SELECT NULLIF(upper(btrim(regexp_replace(p_code,'\s+',' ','g'))),''); $$; CREATE TABLE IF NOT EXISTS public.accounting_debt_suppliers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text, name text NOT NULL, default_payment_term_days integer NOT NULL DEFAULT 30 CHECK(default_payment_term_days BETWEEN 0 AND 3650), note text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES public.profiles(id), updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES public.profiles(id), deleted_at timestamptz, deleted_by uuid REFERENCES public.profiles(id) ); ALTER TABLE public.accounting_debt_suppliers ADD COLUMN IF NOT EXISTS is_active boolean NOT NULL DEFAULT true; DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.accounting_debt_suppliers WHERE public.inventory_normalize_receipt_supplier_code_v1(code) IS NOT NULL GROUP BY public.inventory_normalize_receipt_supplier_code_v1(code) HAVING count(*)>1) THEN RAISE EXCEPTION 'Co ma nha cung cap trung sau khi bo khoang trang/chu hoa thuong. Dung lai va doi chieu, ke ca NCC da ngung.'; END IF; END $$; CREATE UNIQUE INDEX IF NOT EXISTS receipt_supplier_code_unique_all ON public.accounting_debt_suppliers(public.inventory_normalize_receipt_supplier_code_v1(code)) WHERE public.inventory_normalize_receipt_supplier_code_v1(code) IS NOT NULL; CREATE TABLE IF NOT EXISTS public.inventory_receipt_supplier_codes ( code text PRIMARY KEY, supplier_id uuid NOT NULL REFERENCES public.accounting_debt_suppliers(id), reserved_at timestamptz NOT NULL DEFAULT now() ); INSERT INTO public.inventory_receipt_supplier_codes(code,supplier_id) SELECT public.inventory_normalize_receipt_supplier_code_v1(code),id FROM public.accounting_debt_suppliers WHERE public.inventory_normalize_receipt_supplier_code_v1(code) IS NOT NULL ON CONFLICT(code) DO NOTHING; ALTER TABLE public.inventory_receipt_supplier_codes ENABLE ROW LEVEL SECURITY; REVOKE ALL ON TABLE public.inventory_receipt_supplier_codes FROM PUBLIC,anon,authenticated; CREATE OR REPLACE FUNCTION public.inventory_can_manage_receipt_suppliers_v1() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT public.is_approved_active_user() AND (public.is_admin() OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.department='accounting')); $$; CREATE OR REPLACE FUNCTION public.inventory_guard_receipt_supplier_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_owner uuid; v_code text; BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Khong xoa nha cung cap. Hay chon Ngung su dung.'; END IF; IF NOT public.inventory_can_manage_receipt_suppliers_v1() THEN RAISE EXCEPTION 'Chi Ke toan hoac Admin duoc sua nha cung cap.' USING ERRCODE='42501'; END IF; v_code:=public.inventory_normalize_receipt_supplier_code_v1(NEW.code); NEW.name:=btrim(regexp_replace(NEW.name,'\s+',' ','g')); IF NULLIF(NEW.name,'') IS NULL THEN RAISE EXCEPTION 'Vui long nhap ten nha cung cap.'; END IF; IF TG_OP='INSERT' OR NEW.code IS DISTINCT FROM OLD.code OR NEW.name IS DISTINCT FROM OLD.name THEN IF v_code IS NULL THEN RAISE EXCEPTION 'Vui long nhap ma nha cung cap.'; END IF; END IF; IF v_code IS NOT NULL THEN IF length(v_code)>50 THEN RAISE EXCEPTION 'Ma nha cung cap toi da 50 ky tu.'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(v_code,20260930)); SELECT supplier_id INTO v_owner FROM public.inventory_receipt_supplier_codes WHERE code=v_code; IF FOUND AND v_owner<>NEW.id THEN RAISE EXCEPTION 'Ma nha cung cap da duoc su dung, ke ca nha cung cap da ngung.' USING ERRCODE='23505'; END IF; IF TG_OP='UPDATE' THEN INSERT INTO public.inventory_receipt_supplier_codes(code,supplier_id) VALUES(v_code,NEW.id) ON CONFLICT(code) DO NOTHING; END IF; END IF; NEW.code:=v_code; IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); NEW.created_at:=now(); ELSE NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; END IF; NEW.updated_by:=auth.uid(); NEW.updated_at:=now(); IF NEW.deleted_at IS NOT NULL THEN NEW.is_active:=false; END IF; RETURN NEW; END $$; CREATE OR REPLACE FUNCTION public.inventory_reserve_receipt_supplier_code_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NEW.code IS NOT NULL THEN INSERT INTO public.inventory_receipt_supplier_codes(code,supplier_id) VALUES(NEW.code,NEW.id) ON CONFLICT(code) DO NOTHING; END IF; RETURN NEW; END $$; CREATE OR REPLACE TRIGGER zz_receipt_supplier_guard BEFORE INSERT OR UPDATE OR DELETE ON public.accounting_debt_suppliers FOR EACH ROW EXECUTE FUNCTION public.inventory_guard_receipt_supplier_v1(); CREATE OR REPLACE TRIGGER zz_receipt_supplier_reserve AFTER INSERT ON public.accounting_debt_suppliers FOR EACH ROW EXECUTE FUNCTION public.inventory_reserve_receipt_supplier_code_v1(); ALTER TABLE public.accounting_debt_suppliers ENABLE ROW LEVEL SECURITY; DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='accounting_debt_suppliers' AND policyname='receipt_supplier_accounting_select') THEN CREATE POLICY receipt_supplier_accounting_select ON public.accounting_debt_suppliers FOR SELECT TO authenticated USING(public.inventory_can_manage_receipt_suppliers_v1()); END IF; IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='accounting_debt_suppliers' AND policyname='receipt_supplier_accounting_insert') THEN CREATE POLICY receipt_supplier_accounting_insert ON public.accounting_debt_suppliers FOR INSERT TO authenticated WITH CHECK(public.inventory_can_manage_receipt_suppliers_v1()); END IF; IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='accounting_debt_suppliers' AND policyname='receipt_supplier_accounting_update') THEN CREATE POLICY receipt_supplier_accounting_update ON public.accounting_debt_suppliers FOR UPDATE TO authenticated USING(public.inventory_can_manage_receipt_suppliers_v1()) WITH CHECK(public.inventory_can_manage_receipt_suppliers_v1()); END IF; END $$; GRANT SELECT,INSERT,UPDATE ON public.accounting_debt_suppliers TO authenticated; CREATE OR REPLACE FUNCTION public.inventory_list_receipt_suppliers_v1() RETURNS TABLE(id uuid,code text,name text,is_active boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN PERFORM public.require_approved_active_user(); RETURN QUERY SELECT s.id,public.inventory_normalize_receipt_supplier_code_v1(s.code),s.name,s.is_active AND s.deleted_at IS NULL FROM public.accounting_debt_suppliers s ORDER BY public.inventory_normalize_receipt_supplier_code_v1(s.code),s.name,s.id; END $$; CREATE OR REPLACE FUNCTION public.inventory_save_receipt_supplier_v1(p_supplier_id uuid,p_code text,p_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_id uuid; BEGIN IF NOT public.inventory_can_manage_receipt_suppliers_v1() THEN RAISE EXCEPTION 'Chi Ke toan hoac Admin duoc sua nha cung cap.' USING ERRCODE='42501'; END IF; IF NULLIF(btrim(p_code),'') IS NULL OR NULLIF(btrim(p_name),'') IS NULL THEN RAISE EXCEPTION 'Vui long nhap ma va ten nha cung cap.'; END IF; IF p_supplier_id IS NULL THEN INSERT INTO public.accounting_debt_suppliers(code,name) VALUES(p_code,p_name) RETURNING id INTO v_id; ELSE UPDATE public.accounting_debt_suppliers SET code=p_code,name=p_name WHERE id=p_supplier_id AND deleted_at IS NULL AND is_active RETURNING id INTO v_id; IF NOT FOUND THEN RAISE EXCEPTION 'Nha cung cap khong con hoat dong. Tai lai danh sach.'; END IF; END IF; RETURN v_id; END $$; CREATE OR REPLACE FUNCTION public.inventory_deactivate_receipt_supplier_v1(p_supplier_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NOT public.inventory_can_manage_receipt_suppliers_v1() THEN RAISE EXCEPTION 'Chi Ke toan hoac Admin duoc ngung nha cung cap.' USING ERRCODE='42501'; END IF; UPDATE public.accounting_debt_suppliers SET is_active=false WHERE id=p_supplier_id; IF NOT FOUND THEN RAISE EXCEPTION 'Khong tim thay nha cung cap.'; END IF; END $$; ALTER TABLE public.inventory_transactions ADD COLUMN IF NOT EXISTS source_kind text, ADD COLUMN IF NOT EXISTS supplier_id uuid REFERENCES public.accounting_debt_suppliers(id), ADD COLUMN IF NOT EXISTS supplier_code_snapshot text, ADD COLUMN IF NOT EXISTS supplier_name_snapshot text, ADD COLUMN IF NOT EXISTS created_by_name_snapshot text; ALTER TABLE public.phoi_transactions ADD COLUMN IF NOT EXISTS source_kind text, ADD COLUMN IF NOT EXISTS supplier_id uuid REFERENCES public.accounting_debt_suppliers(id), ADD COLUMN IF NOT EXISTS supplier_code_snapshot text, ADD COLUMN IF NOT EXISTS supplier_name_snapshot text, ADD COLUMN IF NOT EXISTS created_by_name_snapshot text; CREATE TABLE IF NOT EXISTS public.inventory_receipt_source_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_kind text NOT NULL CHECK(receipt_kind IN('inventory','phoi')), transaction_id uuid NOT NULL, old_source jsonb NOT NULL, new_source jsonb NOT NULL, reason text NOT NULL, changed_at timestamptz NOT NULL DEFAULT now(), changed_by uuid NOT NULL REFERENCES public.profiles(id) ); CREATE TABLE IF NOT EXISTS public.inventory_receipt_requests ( actor_id uuid NOT NULL REFERENCES public.profiles(id), request_id uuid NOT NULL, action text NOT NULL, payload jsonb NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,request_id) ); ALTER TABLE public.inventory_receipt_source_audit ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inventory_receipt_requests ENABLE ROW LEVEL SECURITY; REVOKE ALL ON TABLE public.inventory_receipt_source_audit,public.inventory_receipt_requests FROM PUBLIC,anon,authenticated; DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='inventory_receipt_source_audit' AND policyname='receipt_audit_manager_read') THEN CREATE POLICY receipt_audit_manager_read ON public.inventory_receipt_source_audit FOR SELECT TO authenticated USING(public.is_manager()); END IF; END $$; GRANT SELECT ON public.inventory_receipt_source_audit TO authenticated; CREATE OR REPLACE FUNCTION public.inventory_guard_receipt_source_v1() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ DECLARE v_parent record; v_supplier record; v_kind text; v_manual boolean; v_changed boolean; v_reason text; BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Khong xoa lich su nhap. Hay dung chuc nang Huy.'; END IF; IF current_user IN('authenticated','anon','authenticator') THEN RAISE EXCEPTION 'Vui long cap nhat trang va luu phieu qua chuc nang Nhap kho/Nhap phoi.' USING ERRCODE='42501'; END IF; v_kind:=CASE WHEN TG_TABLE_NAME='phoi_transactions' THEN 'phoi' ELSE 'inventory' END; v_manual:=v_kind='phoi' OR (to_jsonb(NEW)->>'stocktake_id' IS NULL AND to_jsonb(NEW)->>'shipment_id' IS NULL AND to_jsonb(NEW)->>'delivery_plan_id' IS NULL); IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); NEW.created_at:=now(); SELECT NULLIF(btrim(p.full_name),'') INTO NEW.created_by_name_snapshot FROM public.profiles p WHERE p.id=auth.uid(); IF NEW.adjusted_from_transaction_id IS NOT NULL THEN EXECUTE format('SELECT id,source_kind,supplier_id,supplier_code_snapshot,supplier_name_snapshot FROM public.%I WHERE id=$1 AND deleted_at IS NULL',TG_TABLE_NAME) INTO v_parent USING NEW.adjusted_from_transaction_id; IF v_parent.id IS NULL THEN RAISE EXCEPTION 'Khong tim thay phieu goc de ke thua nguon.'; END IF; NEW.source_kind:=v_parent.source_kind; NEW.supplier_id:=v_parent.supplier_id; NEW.supplier_code_snapshot:=v_parent.supplier_code_snapshot; NEW.supplier_name_snapshot:=v_parent.supplier_name_snapshot; RETURN NEW; END IF; IF NEW.tx_type='in' AND v_manual AND NEW.source_kind IS NULL THEN RAISE EXCEPTION 'Vui long chon Nguon truoc khi nhap. Hay tai lai trang neu dang dung ban cu.'; END IF; v_changed:=NEW.source_kind IS NOT NULL OR NEW.supplier_id IS NOT NULL; ELSE NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; NEW.created_by_name_snapshot:=OLD.created_by_name_snapshot; v_changed:=ROW(NEW.source_kind,NEW.supplier_id) IS DISTINCT FROM ROW(OLD.source_kind,OLD.supplier_id); IF NOT v_changed THEN NEW.supplier_code_snapshot:=OLD.supplier_code_snapshot; NEW.supplier_name_snapshot:=OLD.supplier_name_snapshot; RETURN NEW; END IF; v_reason:=NULLIF(btrim(current_setting('app.receipt_source_reason',true)),''); IF v_reason IS NULL THEN RAISE EXCEPTION 'Vui long nhap ly do thay doi Nguon.'; END IF; IF NEW.source_kind IS NULL THEN RAISE EXCEPTION 'Khong duoc xoa Nguon da ghi nhan.'; END IF; END IF; IF NEW.source_kind IS NOT NULL AND (NOT v_manual OR (NEW.tx_type<>'in' AND NEW.adjusted_from_transaction_id IS NULL)) THEN RAISE EXCEPTION 'Chi phieu nhap thu cong duoc gan Nguon.'; END IF; IF NEW.source_kind='supplier' THEN SELECT s.* INTO v_supplier FROM public.accounting_debt_suppliers s WHERE s.id=NEW.supplier_id AND s.is_active AND s.deleted_at IS NULL AND public.inventory_normalize_receipt_supplier_code_v1(s.code) IS NOT NULL FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Nha cung cap da ngung, chua co ma hoac khong ton tai. Hay chon lai Nguon.'; END IF; NEW.supplier_code_snapshot:=public.inventory_normalize_receipt_supplier_code_v1(v_supplier.code); NEW.supplier_name_snapshot:=v_supplier.name; ELSIF NEW.source_kind='factory' THEN IF NEW.supplier_id IS NOT NULL THEN RAISE EXCEPTION 'Nguon nha may khong duoc kem nha cung cap.'; END IF; NEW.supplier_code_snapshot:=NULL; NEW.supplier_name_snapshot:=NULL; ELSIF NEW.source_kind IS NOT NULL OR NEW.supplier_id IS NOT NULL THEN RAISE EXCEPTION 'Nguon nhap khong hop le.'; ELSE NEW.supplier_code_snapshot:=NULL; NEW.supplier_name_snapshot:=NULL; END IF; IF TG_OP='UPDATE' AND v_changed THEN INSERT INTO public.inventory_receipt_source_audit(receipt_kind,transaction_id,old_source,new_source,reason,changed_by) VALUES(v_kind,NEW.id,jsonb_build_object('source_kind',OLD.source_kind,'supplier_id',OLD.supplier_id,'code',OLD.supplier_code_snapshot,'name',OLD.supplier_name_snapshot),jsonb_build_object('source_kind',NEW.source_kind,'supplier_id',NEW.supplier_id,'code',NEW.supplier_code_snapshot,'name',NEW.supplier_name_snapshot),v_reason,auth.uid()); END IF; RETURN NEW; END $$; CREATE OR REPLACE TRIGGER zz_receipt_source_guard BEFORE INSERT OR UPDATE OR DELETE ON public.inventory_transactions FOR EACH ROW EXECUTE FUNCTION public.inventory_guard_receipt_source_v1(); CREATE OR REPLACE TRIGGER zz_receipt_source_guard BEFORE INSERT OR UPDATE OR DELETE ON public.phoi_transactions FOR EACH ROW EXECUTE FUNCTION public.inventory_guard_receipt_source_v1(); CREATE OR REPLACE FUNCTION public.inventory_receipt_metadata_v1(p_kind text,p_transaction_ids uuid[]) RETURNS TABLE(id uuid,source_kind text,supplier_id uuid,supplier_code_snapshot text,supplier_name_snapshot text,created_by_name_snapshot text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN PERFORM public.require_approved_active_user(); IF p_kind NOT IN('inventory','phoi') OR p_kind IS NULL OR cardinality(p_transaction_ids)>1000 THEN RAISE EXCEPTION 'Danh sach lich su khong hop le.'; END IF; RETURN QUERY EXECUTE format('SELECT t.id,t.source_kind,t.supplier_id,t.supplier_code_snapshot,t.supplier_name_snapshot,COALESCE(NULLIF(btrim(t.created_by_name_snapshot),''''),NULLIF(btrim(p.full_name),'''')) FROM public.%I t LEFT JOIN public.profiles p ON p.id=t.created_by WHERE t.id=ANY($1) AND (t.deleted_at IS NULL OR public.is_manager())',CASE WHEN p_kind='inventory' THEN 'inventory_transactions' ELSE 'phoi_transactions' END) USING p_transaction_ids; END $$; CREATE OR REPLACE FUNCTION public.inventory_create_receipts_v1(p_kind text,p_rows jsonb,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_row record; v_product record; v_request record; v_id uuid; v_ids uuid[]:='{}'; v_result jsonb; v_table text; v_product_id uuid; v_day date; v_bad record; v_previous_batch text:=current_setting('app.inventory_batch_replace',true); BEGIN PERFORM public.require_approved_active_user(); IF NOT public.is_manager() THEN RAISE EXCEPTION 'Ban khong co quyen tao phieu nhap.' USING ERRCODE='42501'; END IF; IF p_kind IS NULL OR p_kind NOT IN('inventory','phoi') OR p_request_id IS NULL OR p_rows IS NULL OR jsonb_typeof(p_rows)<>'array' THEN RAISE EXCEPTION 'Du lieu phieu nhap khong hop le.'; END IF; IF jsonb_array_length(p_rows) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Moi lan nhap tu 1 den 100 dong.'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_request_id::text,20260930)); SELECT * INTO v_request FROM public.inventory_receipt_requests WHERE actor_id=auth.uid() AND request_id=p_request_id; IF FOUND THEN IF v_request.action<>'create:'||p_kind OR v_request.payload<>p_rows THEN RAISE EXCEPTION 'Ma lan luu da dung cho noi dung khac. Hay tai lai va kiem tra lich su.'; END IF; RETURN v_request.result; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows) r WHERE jsonb_typeof(r)<>'object' OR jsonb_typeof(r->'qty') IS DISTINCT FROM 'number') THEN RAISE EXCEPTION 'Dong nhap hoac so luong khong hop le.'; END IF; IF (SELECT count(DISTINCT jsonb_build_array(r->>'source_kind',r->>'supplier_id')) FROM jsonb_array_elements(p_rows) r)<>1 THEN RAISE EXCEPTION 'Mot lan nhap chi duoc dung mot Nguon.'; END IF; v_table:=CASE WHEN p_kind='inventory' THEN 'inventory_transactions' ELSE 'phoi_transactions' END; IF p_kind='inventory' THEN FOR v_product_id IN SELECT DISTINCT (r->>'product_id')::uuid FROM jsonb_array_elements(p_rows) r ORDER BY 1 LOOP PERFORM public.inventory_lock_product(v_product_id); END LOOP; PERFORM set_config('app.inventory_batch_replace','on',true); END IF; FOR v_row IN SELECT * FROM jsonb_to_recordset(p_rows) AS x(tx_date date,product_id uuid,qty numeric,unit_cost numeric,note text,source_kind text,supplier_id uuid) LOOP IF v_row.tx_date IS NULL OR v_row.product_id IS NULL OR v_row.qty IS NULL OR v_row.qty<=0 OR v_row.qty::text IN('NaN','Infinity','-Infinity') OR v_row.source_kind IS NULL THEN RAISE EXCEPTION 'Chon Nguon va nhap du ngay, ma hang, so luong lon hon 0.'; END IF; IF v_row.unit_cost<0 OR v_row.unit_cost::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Don gia phai la so khong am.'; END IF; IF NOT public.inventory_actor_can_change_transaction(v_row.tx_date) THEN RAISE EXCEPTION 'Ban khong co quyen nhap o ngay nay.' USING ERRCODE='42501'; END IF; SELECT * INTO v_product FROM public.products WHERE id=v_row.product_id AND deleted_at IS NULL AND COALESCE(is_active,true) FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Ma hang khong con hoat dong. Hay chon lai.'; END IF; EXECUTE format('INSERT INTO public.%I(tx_date,product_id,customer_id,product_name_snapshot,product_spec_snapshot,tx_type,qty,unit_cost,note,source_kind,supplier_id,created_by,updated_by) VALUES($1,$2,$3,$4,$5,''in'',$6,$7,$8,$9,$10,auth.uid(),auth.uid()) RETURNING id',v_table) INTO v_id USING v_row.tx_date,v_product.id,v_product.customer_id,v_product.name,v_product.spec,v_row.qty,v_row.unit_cost,NULLIF(btrim(v_row.note),''),v_row.source_kind,v_row.supplier_id; v_ids:=array_append(v_ids,v_id); END LOOP; IF p_kind='inventory' THEN PERFORM set_config('app.inventory_batch_replace',COALESCE(v_previous_batch,''),true); FOR v_day IN WITH affected AS (SELECT x.product_id,min(x.tx_date) from_date FROM jsonb_to_recordset(p_rows) AS x(product_id uuid,tx_date date) GROUP BY x.product_id) SELECT from_date FROM affected UNION SELECT t.tx_date::date FROM public.inventory_transactions t JOIN affected a ON a.product_id=t.product_id WHERE t.deleted_at IS NULL AND t.tx_date::date>=a.from_date ORDER BY 1 LOOP WITH affected AS (SELECT x.product_id,min(x.tx_date) from_date FROM jsonb_to_recordset(p_rows) AS x(product_id uuid,tx_date date) GROUP BY x.product_id) SELECT s.product_id,s.current_qty INTO v_bad FROM public.inventory_calculate_product_stock_v1(v_day::text,'1970-01-01',(v_day+1)::text) s JOIN affected a ON a.product_id=s.product_id WHERE a.from_date<=v_day AND s.current_qty<0 LIMIT 1; IF FOUND THEN RAISE EXCEPTION 'Bi chan de bao ve kho: ma %, ngay %, ton am %.',v_bad.product_id,v_day,v_bad.current_qty; END IF; END LOOP; END IF; v_result:=jsonb_build_object('success',true,'inserted_count',cardinality(v_ids),'transaction_ids',v_ids); INSERT INTO public.inventory_receipt_requests(actor_id,request_id,action,payload,result) VALUES(auth.uid(),p_request_id,'create:'||p_kind,p_rows,v_result); RETURN v_result; EXCEPTION WHEN OTHERS THEN PERFORM set_config('app.inventory_batch_replace',COALESCE(v_previous_batch,''),true); RAISE; END $$; CREATE OR REPLACE FUNCTION public.inventory_update_receipt_v1(p_kind text,p_transaction_id uuid,p_tx_date date,p_product_id uuid,p_qty numeric,p_unit_cost numeric,p_note text,p_source_kind text,p_supplier_id uuid,p_source_reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_tx record; v_product record; v_table text; v_json jsonb; v_result jsonb; v_previous text:=current_setting('app.receipt_source_reason',true); v_has_adjustments boolean; v_product_id uuid; BEGIN PERFORM public.require_approved_active_user(); IF p_kind IS NULL OR p_kind NOT IN('inventory','phoi') THEN RAISE EXCEPTION 'Loai phieu nhap khong hop le.'; END IF; v_table:=CASE WHEN p_kind='inventory' THEN 'inventory_transactions' ELSE 'phoi_transactions' END; EXECUTE format('SELECT * FROM public.%I WHERE id=$1 AND deleted_at IS NULL FOR UPDATE',v_table) INTO v_tx USING p_transaction_id; IF v_tx.id IS NULL THEN RAISE EXCEPTION 'Khong tim thay phieu nhap.'; END IF; v_json:=to_jsonb(v_tx); IF v_tx.tx_type<>'in' OR v_tx.adjusted_from_transaction_id IS NOT NULL OR v_json->>'shipment_id' IS NOT NULL OR v_json->>'delivery_plan_id' IS NOT NULL OR v_json->>'stocktake_id' IS NOT NULL THEN RAISE EXCEPTION 'Chi duoc sua phieu nhap thu cong goc.'; END IF; IF NOT public.inventory_actor_can_change_transaction(v_tx.tx_date::date) OR NOT public.inventory_actor_can_change_transaction(p_tx_date) THEN RAISE EXCEPTION 'Ban khong co quyen sua phieu nhap o ngay nay.' USING ERRCODE='42501'; END IF; IF p_tx_date IS NULL OR p_product_id IS NULL OR p_qty IS NULL OR p_qty<=0 OR p_qty::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Thong tin sua phieu nhap khong hop le.'; END IF; IF p_unit_cost<0 OR p_unit_cost::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Don gia phai la so khong am.'; END IF; IF p_source_kind IS NULL AND (v_tx.source_kind IS NOT NULL OR p_supplier_id IS NOT NULL) THEN RAISE EXCEPTION 'Khong duoc xoa Nguon da ghi nhan.'; END IF; IF ROW(p_source_kind,p_supplier_id) IS DISTINCT FROM ROW(v_tx.source_kind,v_tx.supplier_id) AND NULLIF(btrim(p_source_reason),'') IS NULL THEN RAISE EXCEPTION 'Vui long nhap ly do thay doi Nguon.'; END IF; EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE adjusted_from_transaction_id=$1 AND deleted_at IS NULL)',v_table) INTO v_has_adjustments USING p_transaction_id; IF v_has_adjustments AND (p_product_id<>v_tx.product_id OR p_qty<>v_tx.qty OR p_tx_date<>v_tx.tx_date::date) THEN RAISE EXCEPTION 'Phieu da co dieu chinh. Giu ngay, ma va so luong goc; dung Dieu chinh de doi so luong.'; END IF; SELECT * INTO v_product FROM public.products WHERE id=p_product_id AND deleted_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Khong tim thay ma hang.'; END IF; IF p_product_id<>v_tx.product_id AND NOT COALESCE(v_product.is_active,true) THEN RAISE EXCEPTION 'Ma hang moi da ngung su dung.'; END IF; IF p_kind='inventory' THEN FOR v_product_id IN SELECT DISTINCT x FROM unnest(ARRAY[v_tx.product_id,p_product_id]) x ORDER BY x LOOP PERFORM public.inventory_lock_product(v_product_id); END LOOP; UPDATE public.inventory_transactions SET tx_date=CASE WHEN tx_date::date=p_tx_date THEN tx_date ELSE p_tx_date::timestamptz END,product_id=p_product_id,customer_id=CASE WHEN p_product_id=v_tx.product_id THEN v_tx.customer_id ELSE v_product.customer_id END,product_name_snapshot=CASE WHEN p_product_id=v_tx.product_id THEN v_tx.product_name_snapshot ELSE v_product.name END,product_spec_snapshot=CASE WHEN p_product_id=v_tx.product_id THEN v_tx.product_spec_snapshot ELSE v_product.spec END,qty=p_qty,unit_cost=p_unit_cost,note=NULLIF(btrim(p_note),''),updated_by=auth.uid(),updated_at=now() WHERE id=p_transaction_id; v_result:=jsonb_build_object('success',true); ELSE UPDATE public.phoi_transactions SET tx_date=p_tx_date,product_id=p_product_id,customer_id=CASE WHEN p_product_id=v_tx.product_id THEN v_tx.customer_id ELSE v_product.customer_id END,product_name_snapshot=CASE WHEN p_product_id=v_tx.product_id THEN v_tx.product_name_snapshot ELSE v_product.name END,product_spec_snapshot=CASE WHEN p_product_id=v_tx.product_id THEN v_tx.product_spec_snapshot ELSE v_product.spec END,qty=p_qty,unit_cost=p_unit_cost,note=NULLIF(btrim(p_note),''),updated_by=auth.uid(),updated_at=now() WHERE id=p_transaction_id; v_result:=jsonb_build_object('success',true); END IF; IF ROW(p_source_kind,p_supplier_id) IS DISTINCT FROM ROW(v_tx.source_kind,v_tx.supplier_id) THEN PERFORM set_config('app.receipt_source_reason',btrim(p_source_reason),true); EXECUTE format('UPDATE public.%I SET source_kind=$2,supplier_id=$3,updated_at=now(),updated_by=auth.uid() WHERE id=$1 OR (adjusted_from_transaction_id=$1 AND deleted_at IS NULL)',v_table) USING p_transaction_id,p_source_kind,p_supplier_id; PERFORM set_config('app.receipt_source_reason',COALESCE(v_previous,''),true); END IF; RETURN v_result; EXCEPTION WHEN OTHERS THEN PERFORM set_config('app.receipt_source_reason',COALESCE(v_previous,''),true); RAISE; END $$; CREATE OR REPLACE FUNCTION public.inventory_adjust_receipt_v1(p_kind text,p_transaction_id uuid,p_target_qty numeric,p_tx_date date,p_unit_cost numeric,p_note text,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_tx record; v_request record; v_table text; v_payload jsonb; v_current numeric; v_diff numeric; v_result jsonb; v_id uuid; v_json jsonb; BEGIN PERFORM public.require_approved_active_user(); IF p_kind IS NULL OR p_kind NOT IN('inventory','phoi') OR p_request_id IS NULL THEN RAISE EXCEPTION 'Loai phieu dieu chinh khong hop le.'; END IF; IF NOT public.is_manager() THEN RAISE EXCEPTION 'Ban khong co quyen dieu chinh phieu nhap.' USING ERRCODE='42501'; END IF; v_payload:=jsonb_build_object('id',p_transaction_id,'qty',p_target_qty,'date',p_tx_date,'cost',p_unit_cost,'note',p_note); PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_request_id::text,20260930)); SELECT * INTO v_request FROM public.inventory_receipt_requests WHERE actor_id=auth.uid() AND request_id=p_request_id; IF FOUND THEN IF v_request.action<>'adjust:'||p_kind OR v_request.payload<>v_payload THEN RAISE EXCEPTION 'Ma lan luu da dung cho noi dung khac. Hay tai lai va kiem tra lich su.'; END IF; RETURN v_request.result; END IF; v_table:=CASE WHEN p_kind='inventory' THEN 'inventory_transactions' ELSE 'phoi_transactions' END; EXECUTE format('SELECT * FROM public.%I WHERE id=$1 AND deleted_at IS NULL FOR UPDATE',v_table) INTO v_tx USING p_transaction_id; IF v_tx.id IS NULL THEN RAISE EXCEPTION 'Khong tim thay phieu nhap.'; END IF; v_json:=to_jsonb(v_tx); IF v_tx.tx_type<>'in' OR v_tx.adjusted_from_transaction_id IS NOT NULL OR v_json->>'shipment_id' IS NOT NULL OR v_json->>'delivery_plan_id' IS NOT NULL OR v_json->>'stocktake_id' IS NOT NULL THEN RAISE EXCEPTION 'Chi duoc dieu chinh phieu nhap thu cong goc.'; END IF; IF NOT public.inventory_actor_can_change_transaction(v_tx.tx_date::date) OR NOT public.inventory_actor_can_change_transaction(p_tx_date) THEN RAISE EXCEPTION 'Ban khong co quyen dieu chinh phieu nhap o ngay nay.' USING ERRCODE='42501'; END IF; IF p_target_qty IS NULL OR p_target_qty<0 OR p_target_qty::text IN('NaN','Infinity','-Infinity') OR p_tx_date IS NULL OR p_tx_date<v_tx.tx_date::date OR NULLIF(btrim(p_note),'') IS NULL THEN RAISE EXCEPTION 'Nhap so luong dich khong am, ngay khong truoc phieu goc va ly do dieu chinh.'; END IF; IF p_unit_cost<0 OR p_unit_cost::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Don gia phai la so khong am.'; END IF; IF p_kind='inventory' THEN PERFORM public.inventory_lock_product(v_tx.product_id); v_result:=public.inventory_adjust_manual_transaction(p_transaction_id,p_target_qty,p_tx_date,p_unit_cost,p_note); ELSE SELECT v_tx.qty+COALESCE(sum(CASE WHEN a.tx_type='adjust_in' THEN a.qty WHEN a.tx_type='adjust_out' THEN -a.qty ELSE 0 END),0) INTO v_current FROM public.phoi_transactions a WHERE a.adjusted_from_transaction_id=p_transaction_id AND a.deleted_at IS NULL; v_diff:=p_target_qty-v_current; IF v_diff=0 THEN RAISE EXCEPTION 'So luong sau dieu chinh phai khac hien tai.'; END IF; INSERT INTO public.phoi_transactions(tx_date,product_id,customer_id,product_name_snapshot,product_spec_snapshot,qty,unit_cost,note,tx_type,adjusted_from_transaction_id,created_by,updated_by) VALUES(p_tx_date,v_tx.product_id,v_tx.customer_id,v_tx.product_name_snapshot,v_tx.product_spec_snapshot,abs(v_diff),COALESCE(p_unit_cost,v_tx.unit_cost),btrim(p_note),CASE WHEN v_diff>0 THEN 'adjust_in' ELSE 'adjust_out' END,p_transaction_id,auth.uid(),auth.uid()) RETURNING id INTO v_id; v_result:=jsonb_build_object('success',true,'transaction_id',v_id,'adjust_type',CASE WHEN v_diff>0 THEN 'adjust_in' ELSE 'adjust_out' END,'adjust_qty',abs(v_diff)); END IF; INSERT INTO public.inventory_receipt_requests(actor_id,request_id,action,payload,result) VALUES(auth.uid(),p_request_id,'adjust:'||p_kind,v_payload,v_result); RETURN v_result; END $$; CREATE OR REPLACE FUNCTION public.inventory_cancel_receipts_v1(p_kind text,p_transaction_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_count integer; v_adjust_count integer; v_table text; v_tx record; v_requested integer; v_json jsonb; BEGIN PERFORM public.require_approved_active_user(); IF p_kind IS NULL OR p_kind NOT IN('inventory','phoi') OR p_transaction_ids IS NULL OR cardinality(p_transaction_ids) NOT BETWEEN 1 AND 100 OR array_position(p_transaction_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Chon tu 1 den 100 phieu nhap de huy.'; END IF; v_requested:=cardinality(p_transaction_ids); IF (SELECT count(DISTINCT x) FROM unnest(p_transaction_ids) x)<>v_requested THEN RAISE EXCEPTION 'Danh sach phieu bi trung.'; END IF; v_table:=CASE WHEN p_kind='inventory' THEN 'inventory_transactions' ELSE 'phoi_transactions' END; v_count:=0; FOR v_tx IN EXECUTE format('SELECT * FROM public.%I WHERE id=ANY($1) AND deleted_at IS NULL ORDER BY id FOR UPDATE',v_table) USING p_transaction_ids LOOP v_count:=v_count+1; v_json:=to_jsonb(v_tx); IF v_tx.tx_type<>'in' OR v_tx.adjusted_from_transaction_id IS NOT NULL OR v_json->>'shipment_id' IS NOT NULL OR v_json->>'delivery_plan_id' IS NOT NULL OR v_json->>'stocktake_id' IS NOT NULL THEN RAISE EXCEPTION 'Chi duoc huy phieu nhap thu cong goc.'; END IF; IF NOT public.inventory_actor_can_change_transaction(v_tx.tx_date::date) THEN RAISE EXCEPTION 'Ban khong co quyen huy phieu nhap nay.' USING ERRCODE='42501'; END IF; END LOOP; IF v_count<>v_requested THEN RAISE EXCEPTION 'Co phieu da huy hoac khong ton tai. Khong phieu nao thay doi.'; END IF; IF p_kind='inventory' THEN RETURN public.inventory_soft_delete_manual_transactions(p_transaction_ids); END IF; UPDATE public.phoi_transactions SET deleted_at=now(),deleted_by=auth.uid(),updated_at=now(),updated_by=auth.uid(),note=concat_ws(' | ',NULLIF(note,''),'Huy theo phieu goc') WHERE adjusted_from_transaction_id=ANY(p_transaction_ids) AND deleted_at IS NULL; GET DIAGNOSTICS v_adjust_count=ROW_COUNT; UPDATE public.phoi_transactions SET deleted_at=now(),deleted_by=auth.uid(),updated_at=now(),updated_by=auth.uid(),note=concat_ws(' | ',NULLIF(note,''),'Huy phieu nhap; giu lich su') WHERE id=ANY(p_transaction_ids) AND deleted_at IS NULL; GET DIAGNOSTICS v_count=ROW_COUNT; IF v_count<>v_requested THEN RAISE EXCEPTION 'Khong huy du phieu. Toan bo thao tac duoc hoan tac.'; END IF; RETURN jsonb_build_object('success',true,'soft_deleted_count',v_count,'soft_deleted_adjustment_count',v_adjust_count); END $$; DO $$ DECLARE v_function regprocedure; BEGIN FOR v_function IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('inventory_can_manage_receipt_suppliers_v1','inventory_guard_receipt_supplier_v1','inventory_reserve_receipt_supplier_code_v1','inventory_guard_receipt_source_v1','inventory_list_receipt_suppliers_v1','inventory_save_receipt_supplier_v1','inventory_deactivate_receipt_supplier_v1','inventory_receipt_metadata_v1','inventory_create_receipts_v1','inventory_update_receipt_v1','inventory_adjust_receipt_v1','inventory_cancel_receipts_v1') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',v_function); END LOOP; END $$; GRANT EXECUTE ON FUNCTION public.inventory_can_manage_receipt_suppliers_v1(),public.inventory_list_receipt_suppliers_v1(),public.inventory_save_receipt_supplier_v1(uuid,text,text),public.inventory_deactivate_receipt_supplier_v1(uuid),public.inventory_receipt_metadata_v1(text,uuid[]),public.inventory_create_receipts_v1(text,jsonb,uuid),public.inventory_update_receipt_v1(text,uuid,date,uuid,numeric,numeric,text,text,uuid,text),public.inventory_adjust_receipt_v1(text,uuid,numeric,date,numeric,text,uuid),public.inventory_cancel_receipts_v1(text,uuid[]) TO authenticated; NOTIFY pgrst,'reload schema'; COMMIT;
